package com.cowave.search.config

import org.springframework.context.annotation.Bean
import org.springframework.context.annotation.Configuration
import org.springframework.scheduling.TaskScheduler
import org.springframework.scheduling.concurrent.ThreadPoolTaskScheduler

@Configuration
class SchedulerConfig {
    @Bean
    fun taskScheduler(): TaskScheduler =
        ThreadPoolTaskScheduler().apply {
            poolSize = 4
            threadNamePrefix = "dsearch-scheduler-"
            setWaitForTasksToCompleteOnShutdown(true)
            setAwaitTerminationSeconds(30)
            initialize()
        }
}

package com.cowave.search.domain.audit

import jakarta.persistence.Column
import jakarta.persistence.Entity
import jakarta.persistence.GeneratedValue
import jakarta.persistence.GenerationType
import jakarta.persistence.Id
import jakarta.persistence.Table
import java.time.LocalDateTime

@Entity
@Table(name = "audit_logs")
class AuditLog(
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    val id: Long = 0,
    @Column(nullable = false)
    val username: String,
    @Column(nullable = false)
    val action: String,
    @Column(nullable = false)
    val resource: String,
    val detail: String? = null,
    val ipAddress: String? = null,
    @Column(nullable = false)
    val createdAt: LocalDateTime = LocalDateTime.now(),
)

package com.cowave.search.audit.service

import com.cowave.search.audit.infrastructure.AuditLogRepository
import com.cowave.search.domain.audit.AuditLog
import org.springframework.scheduling.annotation.Async
import org.springframework.stereotype.Service

@Service
class AuditLogService(
    private val auditLogRepository: AuditLogRepository,
) {
    @Async
    fun log(
        username: String,
        action: String,
        resource: String,
        detail: String? = null,
        ipAddress: String? = null,
    ) {
        auditLogRepository.save(
            AuditLog(
                username = username,
                action = action,
                resource = resource,
                detail = detail,
                ipAddress = ipAddress,
            ),
        )
    }
}

