package com.cowave.search.auth.service

import com.cowave.search.auth.dto.AuthUserResponse
import com.cowave.search.auth.dto.SignInRequest
import com.cowave.search.auth.infrastructure.UserRepository
import com.cowave.search.auth.infrastructure.UserRoleRepository
import com.cowave.search.common.exception.InvalidPasswordException
import com.cowave.search.common.exception.NotFoundUserException
import com.cowave.search.common.security.JwtUtils
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder
import org.springframework.stereotype.Service

@Service
class AuthService(
    private val userRepository: UserRepository,
    private val userRoleRepository: UserRoleRepository,
    private val passwordEncoder: BCryptPasswordEncoder,
    private val jwtUtils: JwtUtils,
) {
    fun signIn(request: SignInRequest): Pair<AuthUserResponse, String> {
        val user = userRepository.findByEmail(request.email)
            .orElseThrow { NotFoundUserException("존재하지 않는 사용자입니다: ${request.email}") }

        if (!passwordEncoder.matches(request.password, user.password)) {
            throw InvalidPasswordException("비밀번호가 올바르지 않습니다.")
        }

        val roleId = userRoleRepository.findByUserId(user.id)?.roleId

        val token = jwtUtils.sign(
            email = user.email,
            username = user.username,
            roleId = roleId,
        )

        val response = AuthUserResponse(
            id = user.id,
            username = user.username,
            email = user.email,
            roleId = roleId,
            token = token,
        )

        return response to token
    }

    fun getCurrentUser(email: String): AuthUserResponse {
        val user = userRepository.findByEmail(email)
            .orElseThrow { NotFoundUserException("존재하지 않는 사용자입니다: $email") }

        val roleId = userRoleRepository.findByUserId(user.id)?.roleId

        return AuthUserResponse(
            id = user.id,
            username = user.username,
            email = user.email,
            roleId = roleId,
        )
    }
}

package com.cowave.search.auth.service

import com.cowave.search.auth.dto.AddUserRequest
import com.cowave.search.auth.dto.EditProfileRequest
import com.cowave.search.auth.dto.UpdatePasswordRequest
import com.cowave.search.auth.dto.UserResponse
import com.cowave.search.auth.infrastructure.UserRepository
import com.cowave.search.auth.infrastructure.UserRoleRepository
import com.cowave.search.common.exception.DuplicatedUserException
import com.cowave.search.common.exception.InvalidPasswordException
import com.cowave.search.common.exception.NotFoundUserException
import com.cowave.search.domain.auth.User
import com.cowave.search.domain.auth.UserRole
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder
import org.springframework.stereotype.Service
import org.springframework.transaction.annotation.Transactional
import java.time.LocalDateTime
import java.util.UUID

@Service
class UserService(
    private val userRepository: UserRepository,
    private val userRoleRepository: UserRoleRepository,
    private val passwordEncoder: BCryptPasswordEncoder,
) {
    fun findAll(): List<UserResponse> {
        val users = userRepository.findAll()
        val userRoles = userRoleRepository.findAll().associateBy { it.userId }
        return users.map { user ->
            UserResponse.from(user, userRoles[user.id]?.roleId)
        }
    }

    fun findById(id: Long): UserResponse {
        val user = userRepository.findById(id)
            .orElseThrow { NotFoundUserException("존재하지 않는 사용자입니다: $id") }
        val roleId = userRoleRepository.findByUserId(id)?.roleId
        return UserResponse.from(user, roleId)
    }

    @Transactional
    fun create(request: AddUserRequest): UserResponse {
        if (userRepository.existsByEmail(request.email)) {
            throw DuplicatedUserException("이미 사용 중인 이메일입니다: ${request.email}")
        }

        // UUID 앞 5자리로 임시 비밀번호 생성
        val tempPassword = UUID.randomUUID().toString().replace("-", "").take(5)
        val encodedPassword = passwordEncoder.encode(tempPassword)

        val user = userRepository.save(
            User(
                username = request.username,
                email = request.email,
                password = encodedPassword,
            ),
        )

        request.roleId?.let {
            userRoleRepository.save(UserRole(userId = user.id, roleId = it))
        }

        return UserResponse.from(user, request.roleId, tempPassword)
    }

    @Transactional
    fun delete(id: Long) {
        userRepository.findById(id)
            .orElseThrow { NotFoundUserException("존재하지 않는 사용자입니다: $id") }

        // UserRole 먼저 삭제 (참조 무결성)
        userRoleRepository.deleteByUserId(id)
        userRepository.deleteById(id)
    }

    @Transactional
    fun updatePassword(
        id: Long,
        request: UpdatePasswordRequest,
    ): UserResponse {
        val user = userRepository.findById(id)
            .orElseThrow { NotFoundUserException("존재하지 않는 사용자입니다: $id") }

        if (!passwordEncoder.matches(request.password, user.password)) {
            throw InvalidPasswordException("현재 비밀번호가 올바르지 않습니다.")
        }

        user.password = passwordEncoder.encode(request.updatePassword)
        user.updateDate = LocalDateTime.now()
        userRepository.save(user)

        val roleId = userRoleRepository.findByUserId(id)?.roleId
        return UserResponse.from(user, roleId)
    }

    @Transactional
    fun resetPassword(id: Long): UserResponse {
        val user = userRepository.findById(id)
            .orElseThrow { NotFoundUserException("존재하지 않는 사용자입니다: $id") }

        val tempPassword = UUID.randomUUID().toString().replace("-", "").take(5)
        user.password = passwordEncoder.encode(tempPassword)
        user.updateDate = LocalDateTime.now()
        userRepository.save(user)

        val roleId = userRoleRepository.findByUserId(id)?.roleId
        return UserResponse.from(user, roleId, tempPassword)
    }

    @Transactional
    fun editProfile(
        id: Long,
        request: EditProfileRequest,
    ): UserResponse {
        val user = userRepository.findById(id)
            .orElseThrow { NotFoundUserException("존재하지 않는 사용자입니다: $id") }

        if (user.email != request.email && userRepository.existsByEmail(request.email)) {
            throw DuplicatedUserException("이미 사용 중인 이메일입니다: ${request.email}")
        }

        user.username = request.username
        user.email = request.email
        user.updateDate = LocalDateTime.now()
        userRepository.save(user)

        // 역할 변경 처리
        userRoleRepository.deleteByUserId(id)
        request.roleId?.let {
            userRoleRepository.save(UserRole(userId = id, roleId = it))
        }

        return UserResponse.from(user, request.roleId)
    }
}

package com.cowave.search.auth.service

import com.cowave.search.auth.dto.CreateRoleRequest
import com.cowave.search.auth.dto.RoleListResponse
import com.cowave.search.auth.dto.RoleResponse
import com.cowave.search.auth.dto.UserRoleResponse
import com.cowave.search.auth.infrastructure.RoleRepository
import com.cowave.search.auth.infrastructure.UserRoleRepository
import com.cowave.search.common.exception.NotFoundException
import com.cowave.search.domain.auth.Role
import org.springframework.stereotype.Service
import org.springframework.transaction.annotation.Transactional
import java.time.LocalDateTime

@Service
class RoleService(
    private val roleRepository: RoleRepository,
    private val userRoleRepository: UserRoleRepository,
) {
    fun findAll(): RoleListResponse {
        val roles = roleRepository.findAll().map { RoleResponse.from(it) }
        val userRoles = userRoleRepository.findAll().map {
            UserRoleResponse(id = it.id, userId = it.userId, roleId = it.roleId)
        }
        return RoleListResponse(roles = roles, userRoles = userRoles)
    }

    fun findById(id: Long): RoleResponse {
        val role = roleRepository.findById(id)
            .orElseThrow { NotFoundException("존재하지 않는 역할입니다: $id") }
        return RoleResponse.from(role)
    }

    fun create(request: CreateRoleRequest): RoleResponse {
        val role = roleRepository.save(
            Role(
                name = request.name,
                analysis = request.analysis,
                index = request.index,
                search = request.search,
                manage = request.manage,
            ),
        )
        return RoleResponse.from(role)
    }

    @Transactional
    fun update(
        id: Long,
        request: CreateRoleRequest,
    ): RoleResponse {
        val role = roleRepository.findById(id)
            .orElseThrow { NotFoundException("존재하지 않는 역할입니다: $id") }

        role.name = request.name
        role.analysis = request.analysis
        role.index = request.index
        role.search = request.search
        role.manage = request.manage
        role.updateDate = LocalDateTime.now()

        return RoleResponse.from(roleRepository.save(role))
    }

    fun delete(id: Long): RoleResponse {
        val role = roleRepository.findById(id)
            .orElseThrow { NotFoundException("존재하지 않는 역할입니다: $id") }
        roleRepository.delete(role)
        return RoleResponse.from(role)
    }
}

