package com.cowave.search.cluster.service

import com.cowave.search.cluster.dto.ClusterRequest
import com.cowave.search.cluster.dto.ClusterResponse
import com.cowave.search.cluster.dto.ClusterStatusResponse
import com.cowave.search.cluster.infrastructure.ClusterRepository
import com.cowave.search.common.elasticsearch.ElasticsearchClientFactory
import com.cowave.search.common.elasticsearch.ElasticsearchClientFactory.ClusterConnectionInfo
import com.cowave.search.common.elasticsearch.SystemIndexInitializer
import com.cowave.search.common.exception.NotFoundException
import com.cowave.search.domain.cluster.Cluster
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Service
import org.springframework.transaction.annotation.Transactional
import java.time.LocalDateTime
import java.util.UUID

@Service
class ClusterService(
    private val clusterRepository: ClusterRepository,
    private val clientFactory: ElasticsearchClientFactory,
    private val systemIndexInitializer: SystemIndexInitializer,
) {
    private val logger = LoggerFactory.getLogger(ClusterService::class.java)

    fun findAll(includeStatus: Boolean): List<ClusterResponse> =
        clusterRepository.findAll().map { cluster ->
            val status = if (includeStatus) scanClusterStatus(cluster.id) else null
            ClusterResponse.from(cluster, status)
        }

    fun findById(id: UUID): ClusterResponse {
        val cluster = clusterRepository.findById(id)
            .orElseThrow { NotFoundException("존재하지 않는 클러스터입니다: $id") }
        val status = scanClusterStatus(id)
        return ClusterResponse.from(cluster, status)
    }

    @Transactional
    fun create(request: ClusterRequest): ClusterResponse {
        val cluster = clusterRepository.save(
            Cluster(
                name = request.name,
                scheme = request.scheme,
                host = request.host,
                port = request.port,
                kibana = request.kibana,
                theme = request.theme,
                username = request.username,
                password = request.password,
                dictionaryRemoteClusterId = request.dictionaryRemoteClusterId,
                autocompleteUrl = request.autocompleteUrl,
            ),
        )

        // 클라이언트 팩토리에 등록
        clientFactory.registerCluster(
            ClusterConnectionInfo(
                id = cluster.id,
                scheme = cluster.scheme,
                host = cluster.host,
                port = cluster.port,
                username = cluster.username,
                password = cluster.password,
            ),
        )

        // dsearch-* 시스템 인덱스 초기화
        systemIndexInitializer.initialize(cluster.id)

        return ClusterResponse.from(cluster)
    }

    @Transactional
    fun delete(
        id: UUID,
        removeData: Boolean,
    ): ClusterResponse {
        val cluster = clusterRepository.findById(id)
            .orElseThrow { NotFoundException("존재하지 않는 클러스터입니다: $id") }

        if (removeData) {
            deleteSystemIndices(id)
        }

        clientFactory.evictCluster(id)
        clusterRepository.delete(cluster)

        return ClusterResponse.from(cluster)
    }

    @Transactional
    fun update(
        id: UUID,
        request: ClusterRequest,
    ): ClusterResponse {
        val cluster = clusterRepository.findById(id)
            .orElseThrow { NotFoundException("존재하지 않는 클러스터입니다: $id") }

        cluster.name = request.name
        cluster.scheme = request.scheme
        cluster.host = request.host
        cluster.port = request.port
        cluster.kibana = request.kibana
        cluster.theme = request.theme
        cluster.username = request.username
        cluster.password = request.password
        cluster.dictionaryRemoteClusterId = request.dictionaryRemoteClusterId
        cluster.autocompleteUrl = request.autocompleteUrl
        cluster.updateDate = LocalDateTime.now()

        // 연결 정보가 변경되었으므로 클라이언트 재등록
        clientFactory.evictCluster(id)
        clientFactory.registerCluster(
            ClusterConnectionInfo(
                id = cluster.id,
                scheme = cluster.scheme,
                host = cluster.host,
                port = cluster.port,
                username = cluster.username,
                password = cluster.password,
            ),
        )

        return ClusterResponse.from(clusterRepository.save(cluster))
    }

    private fun scanClusterStatus(clusterId: UUID): ClusterStatusResponse {
        return runCatching {
            val client = clientFactory.getClient(clusterId)

            // 노드 정보 수집
            val nodesResponse = client.nodes().info { it.metric("_all") }
            val nodeCount = nodesResponse.nodes().size

            // 클러스터 통계 수집
            val statsResponse = client.cluster().stats { }
            val shardCount = statsResponse.indices().shards().total().toInt()
            val indexCount = statsResponse.indices().count().toInt()
            val storeSizeBytes = statsResponse.indices().store().sizeInBytes()
            val storeSize = formatBytes(storeSizeBytes)

            ClusterStatusResponse(
                connection = true,
                nodeCount = nodeCount,
                shardCount = shardCount,
                indexCount = indexCount,
                storeSize = storeSize,
            )
        }.getOrElse { e ->
            logger.warn("클러스터 {} 상태 조회 실패: {}", clusterId, e.message)
            ClusterStatusResponse(connection = false)
        }
    }

    private fun deleteSystemIndices(clusterId: UUID) {
        runCatching {
            val client = clientFactory.getClient(clusterId)
            SystemIndexInitializer.SYSTEM_INDICES.forEach { indexName ->
                runCatching {
                    client.indices().delete { it.index(indexName) }
                    logger.info("클러스터 {} 시스템 인덱스 삭제: {}", clusterId, indexName)
                }.onFailure { e ->
                    logger.warn("클러스터 {} 시스템 인덱스 {} 삭제 실패: {}", clusterId, indexName, e.message)
                }
            }
        }.onFailure { e ->
            logger.warn("클러스터 {} 데이터 삭제 중 오류: {}", clusterId, e.message)
        }
    }

    private fun formatBytes(bytes: Long): String {
        val kb = bytes / 1024.0
        val mb = kb / 1024.0
        val gb = mb / 1024.0
        return when {
            gb >= 1 -> "%.1fgb".format(gb)
            mb >= 1 -> "%.1fmb".format(mb)
            kb >= 1 -> "%.1fkb".format(kb)
            else -> "${bytes}b"
        }
    }
}

