import org.slf4j.LoggerFactory
import org.springframework.boot.ApplicationArguments
import org.springframework.boot.ApplicationRunner
import org.springframework.stereotype.Component

/**
 * 애플리케이션 시작 시 DB에 저장된 클러스터를 ES 클라이언트 팩토리에 등록.
 * 서버 재시작 시에도 클라이언트 캐시가 자동 복원된다.
 */
@Component
class ClusterInitializer(
    private val clusterRepository: ClusterRepository,
    private val clientFactory: ElasticsearchClientFactory,
) : ApplicationRunner {
    private val logger = LoggerFactory.getLogger(ClusterInitializer::class.java)

    override fun run(args: ApplicationArguments) {
        val clusters = clusterRepository.findAll()
        logger.info("저장된 클러스터 {}개를 ES 클라이언트 팩토리에 등록합니다.", clusters.size)

        clusters.forEach { cluster ->
            runCatching {
                clientFactory.registerCluster(
                    ClusterConnectionInfo(
                        id = cluster.id,
                        scheme = cluster.scheme,
                        host = cluster.host,
                        port = cluster.port,
                        username = cluster.username,
                        password = cluster.password,
                    ),
                )
            }.onFailure { e ->
                logger.warn("클러스터 {} ({}) 등록 실패: {}", cluster.id, cluster.name, e.message)
            }
        }

        logger.info("클러스터 초기화 완료: {}개 등록", clientFactory.registeredClusterIds().size)
    }
}

