package com.cowave.search.auth.service

import com.cowave.search.auth.dto.AddUserRequest
import com.cowave.search.auth.dto.EditProfileRequest
import com.cowave.search.auth.dto.UpdatePasswordRequest
import com.cowave.search.auth.dto.UserResponse
import com.cowave.search.auth.infrastructure.UserRepository
import com.cowave.search.auth.infrastructure.UserRoleRepository
import com.cowave.search.common.exception.DuplicatedUserException
import com.cowave.search.common.exception.InvalidPasswordException
import com.cowave.search.common.exception.NotFoundUserException
import com.cowave.search.domain.auth.User
import com.cowave.search.domain.auth.UserRole
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder
import org.springframework.stereotype.Service
import org.springframework.transaction.annotation.Transactional
import java.time.LocalDateTime
import java.util.UUID

@Service
class UserService(
    private val userRepository: UserRepository,
    private val userRoleRepository: UserRoleRepository,
    private val passwordEncoder: BCryptPasswordEncoder,
) {
    fun findAll(): List<UserResponse> {
        val users = userRepository.findAll()
        val userRoles = userRoleRepository.findAll().associateBy { it.userId }
        return users.map { user ->
            UserResponse.from(user, userRoles[user.id]?.roleId)
        }
    }

    fun findById(id: Long): UserResponse {
        val user = userRepository.findById(id)
            .orElseThrow { NotFoundUserException("존재하지 않는 사용자입니다: $id") }
        val roleId = userRoleRepository.findByUserId(id)?.roleId
        return UserResponse.from(user, roleId)
    }

    @Transactional
    fun create(request: AddUserRequest): UserResponse {
        if (userRepository.existsByEmail(request.email)) {
            throw DuplicatedUserException("이미 사용 중인 이메일입니다: ${request.email}")
        }

        // UUID 앞 5자리로 임시 비밀번호 생성
        val tempPassword = UUID.randomUUID().toString().replace("-", "").take(5)
        val encodedPassword: String = passwordEncoder.encode(tempPassword)

        val user = userRepository.save(
            User(
                username = request.username,
                email = request.email,
                password = encodedPassword,
            ),
        )

        request.roleId?.let {
            userRoleRepository.save(UserRole(userId = user.id, roleId = it))
        }

        return UserResponse.from(user, request.roleId, tempPassword)
    }

    @Transactional
    fun delete(id: Long) {
        userRepository.findById(id)
            .orElseThrow { NotFoundUserException("존재하지 않는 사용자입니다: $id") }

        // UserRole 먼저 삭제 (참조 무결성)
        userRoleRepository.deleteByUserId(id)
        userRepository.deleteById(id)
    }

    @Transactional
    fun updatePassword(
        id: Long,
        request: UpdatePasswordRequest,
    ): UserResponse {
        val user = userRepository.findById(id)
            .orElseThrow { NotFoundUserException("존재하지 않는 사용자입니다: $id") }

        if (!passwordEncoder.matches(request.password, user.password)) {
            throw InvalidPasswordException("현재 비밀번호가 올바르지 않습니다.")
        }

        user.password = passwordEncoder.encode(request.updatePassword)
        user.updateDate = LocalDateTime.now()
        userRepository.save(user)

        val roleId = userRoleRepository.findByUserId(id)?.roleId
        return UserResponse.from(user, roleId)
    }

    @Transactional
    fun resetPassword(id: Long): UserResponse {
        val user = userRepository.findById(id)
            .orElseThrow { NotFoundUserException("존재하지 않는 사용자입니다: $id") }

        val tempPassword = UUID.randomUUID().toString().replace("-", "").take(5)
        user.password = passwordEncoder.encode(tempPassword)
        user.updateDate = LocalDateTime.now()
        userRepository.save(user)

        val roleId = userRoleRepository.findByUserId(id)?.roleId
        return UserResponse.from(user, roleId, tempPassword)
    }

    @Transactional
    fun editProfile(
        id: Long,
        request: EditProfileRequest,
    ): UserResponse {
        val user = userRepository.findById(id)
            .orElseThrow { NotFoundUserException("존재하지 않는 사용자입니다: $id") }

        if (user.email != request.email && userRepository.existsByEmail(request.email)) {
            throw DuplicatedUserException("이미 사용 중인 이메일입니다: ${request.email}")
        }

        user.username = request.username
        user.email = request.email
        user.updateDate = LocalDateTime.now()
        userRepository.save(user)

        // 역할 변경 처리
        userRoleRepository.deleteByUserId(id)
        request.roleId?.let {
            userRoleRepository.save(UserRole(userId = id, roleId = it))
        }

        return UserResponse.from(user, request.roleId)
    }
}

